use serde_json::Value;

pub fn solve(input: Value) -> Value {
    match input {
        Value::Array(arr) if arr.is_empty() => Value::Null,
        Value::Array(arr) => {
            let mut min_val = i64::MAX;
            let mut max_val = i64::MIN;
            for item in arr {
                if let Value::Number(num) = item {
                    if let Some(n) = num.as_i64() {
                        if n < min_val {
                            min_val = n;
                        }
                        if n > max_val {
                            max_val = n;
                        }
                    }
                }
            }
            Value::Array(vec![Value::Number(serde_json::Number::from(min_val)), Value::Number(serde_json::Number::from(max_val))])
        },
        _ => Value::Null,
    }
}
